BEGIN;
CREATE TABLE memory_revalidation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,fact_id uuid NOT NULL REFERENCES memory_items(id) ON DELETE CASCADE,code_symbol_version_id uuid NOT NULL REFERENCES code_symbol_versions(id) ON DELETE CASCADE,previous_snapshot_id uuid REFERENCES code_repository_snapshots(id),current_snapshot_id uuid NOT NULL REFERENCES code_repository_snapshots(id),classification text NOT NULL CHECK (classification IN ('unchanged','renamed','changed','deleted','ambiguous')),outcome text NOT NULL DEFAULT 'unresolved' CHECK (outcome IN ('still-valid','needs-review','superseded','invalidated','unresolved')),status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','resolved','dismissed')),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,resolved_by uuid,UNIQUE(fact_id,code_symbol_version_id,current_snapshot_id));
CREATE INDEX memory_revalidation_events_queue_idx ON memory_revalidation_events(tenant_id,status,created_at);
CREATE INDEX memory_revalidation_events_fact_idx ON memory_revalidation_events(tenant_id,fact_id,created_at DESC);
CREATE TABLE memory_revalidation_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,event_id uuid NOT NULL REFERENCES memory_revalidation_events(id) ON DELETE CASCADE,fact_id uuid NOT NULL REFERENCES memory_items(id) ON DELETE CASCADE,proposed_outcome text NOT NULL CHECK (proposed_outcome IN ('still-valid','superseded','invalidated')),proposed_content text,rationale text NOT NULL DEFAULT '',model text,status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','withdrawn')),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,decided_by uuid,UNIQUE(event_id));
CREATE INDEX memory_revalidation_proposals_queue_idx ON memory_revalidation_proposals(tenant_id,status,created_at);
ALTER TABLE memory_revalidation_events ENABLE ROW LEVEL SECURITY;ALTER TABLE memory_revalidation_events FORCE ROW LEVEL SECURITY;ALTER TABLE memory_revalidation_proposals ENABLE ROW LEVEL SECURITY;ALTER TABLE memory_revalidation_proposals FORCE ROW LEVEL SECURITY;
CREATE POLICY memory_revalidation_events_access ON memory_revalidation_events FOR ALL USING (tenant_id=NULLIF(current_setting('scos.tenant_id',true),'')::uuid AND EXISTS (SELECT 1 FROM memory_items i JOIN namespace_memberships m ON m.namespace_id=i.namespace_id WHERE i.id=memory_revalidation_events.fact_id AND m.principal_id=NULLIF(current_setting('scos.principal_id',true),'')::uuid AND m.can_read)) WITH CHECK (tenant_id=NULLIF(current_setting('scos.tenant_id',true),'')::uuid);
CREATE POLICY memory_revalidation_proposals_access ON memory_revalidation_proposals FOR ALL USING (tenant_id=NULLIF(current_setting('scos.tenant_id',true),'')::uuid AND EXISTS (SELECT 1 FROM memory_items i JOIN namespace_memberships m ON m.namespace_id=i.namespace_id WHERE i.id=memory_revalidation_proposals.fact_id AND m.principal_id=NULLIF(current_setting('scos.principal_id',true),'')::uuid AND m.can_read)) WITH CHECK (tenant_id=NULLIF(current_setting('scos.tenant_id',true),'')::uuid);
ALTER TABLE memory_standing_answers ADD COLUMN invalidated_at timestamptz;CREATE INDEX memory_standing_answers_valid_idx ON memory_standing_answers(tenant_id,namespace_id,question_key) WHERE invalidated_at IS NULL;
CREATE OR REPLACE FUNCTION queue_stale_memory_revalidation(p_snapshot uuid) RETURNS integer LANGUAGE plpgsql AS $function$
DECLARE n integer;BEGIN
WITH linked AS (SELECT DISTINCT l.tenant_id,l.fact_id,l.code_symbol_version_id old_version,oldv.snapshot_id old_snapshot,oldv.symbol_id,newv.id new_version,newv.path new_path,newv.fully_qualified_name new_name,oldv.path old_path,oldv.fully_qualified_name old_name,oldv.content_hash old_hash,newv.content_hash new_hash,CASE WHEN newv.id IS NULL THEN 'deleted' WHEN newv.content_hash=oldv.content_hash AND (newv.path<>oldv.path OR newv.fully_qualified_name<>oldv.fully_qualified_name) THEN 'renamed' WHEN newv.content_hash=oldv.content_hash THEN 'unchanged' ELSE 'changed' END classification FROM memory_code_links l JOIN code_symbol_versions oldv ON oldv.id=l.code_symbol_version_id LEFT JOIN code_symbol_versions newv ON newv.snapshot_id=p_snapshot AND newv.symbol_id=oldv.symbol_id WHERE l.link_type IN ('evidences','motivated_by') AND oldv.snapshot_id<>p_snapshot AND EXISTS (SELECT 1 FROM code_repository_snapshots s WHERE s.id=p_snapshot AND s.tenant_id=l.tenant_id))
INSERT INTO memory_revalidation_events(tenant_id,fact_id,code_symbol_version_id,previous_snapshot_id,current_snapshot_id,classification,outcome,evidence) SELECT tenant_id,fact_id,old_version,old_snapshot,p_snapshot,classification,CASE WHEN classification='renamed' THEN 'still-valid' ELSE 'needs-review' END,jsonb_build_object('old_path',old_path,'new_path',new_path,'old_name',old_name,'new_name',new_name,'old_hash',old_hash,'new_hash',new_hash,'new_symbol_version_id',new_version) FROM linked WHERE classification<>'unchanged' ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;
INSERT INTO memory_revalidation_proposals(tenant_id,event_id,fact_id,proposed_outcome,rationale,model) SELECT e.tenant_id,e.id,e.fact_id,'still-valid','Code continuity requires review before changing linked memory.','pending-review' FROM memory_revalidation_events e WHERE e.current_snapshot_id=p_snapshot AND e.classification IN ('changed','deleted','ambiguous') ON CONFLICT(event_id) DO NOTHING;
UPDATE memory_standing_answers sa SET invalidated_at=now(),refresh_reason='linked code evidence requires revalidation' WHERE sa.invalidated_at IS NULL AND sa.evidence_fact_ids<>'' AND EXISTS (SELECT 1 FROM memory_revalidation_events e WHERE e.current_snapshot_id=p_snapshot AND e.fact_id::text=ANY(SELECT jsonb_array_elements_text(sa.evidence_fact_ids::jsonb)) AND e.classification IN ('changed','deleted','ambiguous'));RETURN n;END;$function$;
COMMIT;